    a = 8'h00; b = 8'hFE;
    if (a + b inside {8'sh80}) m0 = 1; else m0 = 0;
    if (a + b inside {8'sh80}) m1 = 1; else if (a + b inside {8'h55}) m1 = 2; else m1 = 0;
